use vstd::prelude::*;

verus! {
    fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
        requires
            s1.len() == s2.len() && s2.len() == s3.len(),
            s1.len() <= i32::MAX as usize,
        ensures
            res.len() == 3 * s1.len(),
            forall|i: nat| (i < s1.len() as nat) ==> (res[3 * i] == s1[i] && res[3 * i + 1] == s2[i] && res[3 * i + 2] == s3[i]),
    {
        let n = s1.len() as nat;
        let mut res: Vec<i32> = Vec::new();
        res.resize(3 * n as usize, 0); // Initialize the result vector with zeros

        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                res.len() == 3 * n as usize,
                forall|j: nat| (j < i) ==> (res[3 * j] == s1[j] && res[3 * j + 1] == s2[j] && res[3 * j + 2] == s3[j]),
            decreases n - i,
        {
            res[3 * i] = s1[i];
            res[3 * i + 1] = s2[i];
            res[3 * i + 2] = s3[i];
            i = i + 1;
        }
        res
    }
}
